                    }
                }
            }
        },
        "lint": {
            "executor": "@nx/eslint:lint"
        },
        "migrate": {
            "dependsOn": ["build"],
            "executor": "nx:run-commands",
            "cache": false,
            "options": {
                "cwd": "{projectRoot}",
                "command": "ts-node ./src/main.ts"
            }
