import { spawnSync } from 'node:child_process';

import { ExecutorContext } from '@nx/devkit';

import { assertDefined, getDockerResourceName } from '../common';
import { default as waitForHealthContainer } from '../wait-for-healthy-container/executor';

import { PrismaMigrateDeployExecutorSchema } from './schema';

export default async function runExecutor(options: PrismaMigrateDeployExecutorSchema, context: ExecutorContext): Promise<{ success: boolean }> {
    await waitForHealthContainer({ containerName: getDockerResourceName(options.dbProjectName) });

    const projectGraph = assertDefined(context.projectGraph);
    const projectNode = projectGraph.nodes[options.dbProjectName];
    if (!projectNode) {
        throw Error(`No such Nx project: ${options.dbProjectName}`);
    }
    spawnSync('npx', ['prisma', 'migrate', 'deploy'], {
        cwd: projectNode.data.root,
        stdio: 'inherit',
    });
    return { success: true };
}

