"use strict";

/**
 * Load before Next.js so `_log.bootstrap`, `_log.event`, etc. run after `console` and
 * `next/dist/build/output/log` are patched (instrumentation runs too late for dev startup banners).
 */
process.env.NEXT_LOGGER_PRELOADED = "1";
require("pino");
require("next-logger");
// Dev server prints request lines via raw stdout; parse those into JSON. Not used in production
// (`next start`) — the interceptor buffers every write and adds overhead without matching patterns.
if (process.env.NODE_ENV !== "production") {
  require("./dev-stdout-json.cjs");
}
